"""Kiểm khuôn kịch bản chi tiết EAT IN THE KITCHEN (văn bản thuần, khuôn của 02).

Dùng: python -X utf8 kiem_kich_ban.py <file.txt> [--cum-dau N --cum-cuoi M]
In ra lỗi (LOI) và cảnh báo (CANH BAO) theo từng cụm.
"""
import re
import sys

RE_CUM = re.compile(r"^CỤM (\d+) — ")
RE_TAP = re.compile(r"^TẬP (\d+) — ")
RE_SHOT = re.compile(r"^\[\s*(\d+)–\s*(\d+)\s*s\]")
RE_THOAI = re.compile(r"^ {10}([A-ZÀ-Ỹ][A-ZÀ-Ỹ .'’\-]+?): (.*)$")


def kiem(duong_dan, cum_dau=1, cum_cuoi=70):
    with open(duong_dan, encoding="utf-8") as f:
        dong = f.read().splitlines()

    loi, canh_bao = [], []
    cac_cum, cac_tap = [], []
    hien_tai = None

    def dong_cum():
        if hien_tai is None:
            return
        n = hien_tai["so"]
        shots = hien_tai["shots"]
        if not shots:
            loi.append(f"C{n}: không có shot")
            return
        if shots[0][0] != 0:
            loi.append(f"C{n}: shot đầu không bắt đầu ở 0s")
        for (a1, b1, _), (a2, b2, _) in zip(shots, shots[1:]):
            if a2 != b1:
                loi.append(f"C{n}: mốc giây không liền ({a1}–{b1} rồi {a2}–{b2})")
        if shots[-1][1] != 30:
            loi.append(f"C{n}: shot cuối kết ở {shots[-1][1]}s, không phải 30s")
        if not 7 <= len(shots) <= 10:
            canh_bao.append(f"C{n}: {len(shots)} shot (chuẩn 7–10)")
        for a, b, so_thoai in shots:
            if b - a > 5:
                canh_bao.append(f"C{n}: shot {a}–{b}s dài {b - a}s")
            if b - a < 1:
                loi.append(f"C{n}: shot {a}–{b}s dài < 1s")
            if so_thoai > 1:
                canh_bao.append(f"C{n}: shot {a}–{b}s có {so_thoai} câu thoại")
        if shots[-1][2]:
            loi.append(f"C{n}: shot cuối có thoại")
        if len(hien_tai["thoai"]) > 6:
            canh_bao.append(f"C{n}: {len(hien_tai['thoai'])} câu thoại (tối đa 6)")
        if not hien_tai["ket"]:
            loi.append(f"C{n}: thiếu KẾT")
        if not hien_tai["moc"]:
            loi.append(f"C{n}: thiếu MÓC")
        for k in ("nhan_vat", "tinh_than"):
            if not hien_tai[k]:
                loi.append(f"C{n}: thiếu dòng {k}")
        cac_cum.append(hien_tai)

    for i, d in enumerate(dong, 1):
        if len(d) > 120:
            canh_bao.append(f"dòng {i}: dài {len(d)} ký tự")
        m = RE_TAP.match(d)
        if m:
            cac_tap.append((int(m.group(1)), i))
            continue
        m = RE_CUM.match(d)
        if m:
            dong_cum()
            hien_tai = {"so": int(m.group(1)), "dong": i, "shots": [], "thoai": [],
                        "ket": False, "moc": False, "nhan_vat": False, "tinh_than": False}
            continue
        if hien_tai is None:
            continue
        if d.startswith("Nhân vật:"):
            hien_tai["nhan_vat"] = True
        elif d.startswith("Tinh thần:"):
            hien_tai["tinh_than"] = True
        elif d.startswith("KẾT:"):
            hien_tai["ket"] = True
        elif d.startswith("MÓC:"):
            hien_tai["moc"] = True
        m = RE_SHOT.match(d)
        if m:
            hien_tai["shots"].append([int(m.group(1)), int(m.group(2)), 0])
            continue
        m = RE_THOAI.match(d)
        if m:
            ten, cau = m.group(1), m.group(2)
            hien_tai["thoai"].append((ten, cau))
            if hien_tai["shots"]:
                hien_tai["shots"][-1][2] += 1
            else:
                loi.append(f"C{hien_tai['so']}: thoại trước shot đầu (dòng {i})")
            khong_ascii = sorted({c for c in cau if ord(c) > 126})
            if khong_ascii:
                loi.append(f"C{hien_tai['so']}: thoại có ký tự ngoài ASCII {khong_ascii}: {cau}")
            so_tu = len(cau.split())
            if so_tu > 12:
                loi.append(f"C{hien_tai['so']}: câu {so_tu} từ: {ten}: {cau}")
            elif so_tu > 10:
                canh_bao.append(f"C{hien_tai['so']}: câu {so_tu} từ: {ten}: {cau}")
    dong_cum()

    so_cum = [c["so"] for c in cac_cum]
    mong_doi = list(range(cum_dau, cum_cuoi + 1))
    if so_cum != mong_doi:
        thieu = sorted(set(mong_doi) - set(so_cum))
        thua = sorted(set(so_cum) - set(mong_doi))
        lap = sorted({x for x in so_cum if so_cum.count(x) > 1})
        loi.append(f"Thứ tự cụm sai. Thiếu {thieu}, thừa {thua}, lặp {lap}")

    so_thoai = sum(len(c["thoai"]) for c in cac_cum)
    print(f"Cụm: {len(cac_cum)} · Tập: {[t for t, _ in cac_tap]} · Câu thoại: {so_thoai}")
    for x in loi:
        print("LOI      ", x)
    for x in canh_bao:
        print("CANH BAO ", x)
    print(f"Tổng: {len(loi)} lỗi, {len(canh_bao)} cảnh báo")
    return cac_cum


if __name__ == "__main__":
    args = sys.argv[1:]
    dau, cuoi = 1, 70
    if "--cum-dau" in args:
        dau = int(args[args.index("--cum-dau") + 1])
    if "--cum-cuoi" in args:
        cuoi = int(args[args.index("--cum-cuoi") + 1])
    kiem(args[0], dau, cuoi)

